"tos.manage_settings":"\u064a\u0645\u0643\u0646\u0643 \u0625\u062f\u0627\u0631\u0629 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0643.","tos.and":"\u0648","button.agree":"\u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0648\u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629","button.exit":"\u0627\u0644\u062e\u0631\u0648\u062c","privacy.title":"\u0625\u0634\u0639\u0627\u0631 \u062e\u0635\u0648\u0635\u064a\u0629 Pomelli",
"privacy.intro":"\u064a\u0648\u0636\u062d \u0647\u0630\u0627 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u060c \u0625\u0644\u0649 \u062c\u0627\u0646\u0628","privacy.policy_link":"\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629","privacy.intro_end":"\u0644\u062f\u064a\u0646\u0627\u060c \u0643\u064a\u0641\u064a\u0629 \u062a\u0639\u0627\u0645\u0644 Pomelli \u0645\u0639 \u0628\u064a\u0627\u0646\u0627\u062a\u0643. \u064a\u0631\u062c\u0649 \u0642\u0631\u0627\u0621\u062a\u0647\u0645\u0627 \u0628\u0639\u0646\u0627\u064a\u0629.",
"privacy.collection":"\u0639\u0646\u062f \u0627\u0633\u062a\u062e\u062f\u0627\u0645 Pomelli\u060c \u062a\u062c\u0645\u0639 Google \u0645\u0644\u0641\u0643 \u0627\u0644\u062a\u062c\u0627\u0631\u064a\u060c \u0628\u0645\u0627 \u0641\u064a \u0630\u0644\u0643 \u0634\u0639\u0627\u0631\u0643 \u0648\u0623\u0644\u0648\u0627\u0646 \u0639\u0644\u0627\u0645\u062a\u0643 \u0627\u0644\u062a\u062c\u0627\u0631\u064a\u0629 \u0648\u0627\u0644\u062e\u0637\u0648\u0637 \u0648\u0627\u0644\u0635\u0648\u0631\u060c \u0625\u0636\u0627\u0641\u0629\u064b \u0625\u0644\u0649 \u0628\u064a\u0627\u0646\u0627\u062a \u062d\u0645\u0644\u0627\u062a\u0643\u060c \u0628\u0645\u0627 \u0641\u064a \u0630\u0644\u0643 \u0623\u064a \u0645\u0637\u0627\u0644\u0628\u0627\u062a \u0623\u0648 \u0645\u062d\u062a\u0648\u0649 \u062a\u0646\u0634\u0626\u0647\u060c \u0648\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u062d\u0648\u0644 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0645\u064a\u0632\u0627\u062a\u060c \u0648\u0645\u0644\u0627\u062d\u0638\u0627\u062a\u0643. \u062a\u0633\u062a\u062e\u062f\u0645 Google \u0647\u0630\u0647 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0628\u0645\u0627 \u064a\u062a\u0648\u0627\u0641\u0642 \u0645\u0639",
"privacy.collection_end":"\u0648\u0625\u0639\u062f\u0627\u062f\u0627\u062a\u0643 \u0641\u064a Pomelli\u060c \u0648\u0630\u0644\u0643 \u0644\u0623\u063a\u0631\u0627\u0636 \u062a\u0634\u0645\u0644 \u062a\u0642\u062f\u064a\u0645 \u0648\u062a\u062d\u0633\u064a\u0646 \u0648\u062a\u0637\u0648\u064a\u0631 \u0645\u0646\u062a\u062c\u0627\u062a Google \u0648\u062e\u062f\u0645\u0627\u062a\u0647\u0627 \u0648\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0627\u0644\u062a\u0648\u0644\u064a\u062f\u064a. \u0644\u0637\u0644\u0628 \u062d\u0630\u0641 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0643\u060c \u064a\u0631\u062c\u0649 \u0645\u0631\u0627\u0633\u0644\u062a\u0646\u0627 \u0639\u0628\u0631 \u0627\u0644\u0628\u0631\u064a\u062f \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a: pomelli-help@google.com.",
"privacy.protection":"\u0646\u062d\u0646 \u0646\u062a\u062e\u0630 \u062e\u0637\u0648\u0627\u062a \u062c\u062f\u0651\u064a\u0629 \u0644\u062d\u0645\u0627\u064a\u0629 \u062e\u0635\u0648\u0635\u064a\u062a\u0643. \u0642\u062f \u062a\u062a\u0645 \u0645\u0631\u0627\u062c\u0639\u0629 \u0639\u064a\u0646\u0629 \u0639\u0634\u0648\u0627\u0626\u064a\u0629 \u0645\u0646 \u0628\u064a\u0627\u0646\u0627\u062a Pomelli \u0645\u0646 \u0642\u0628\u0644 \u0645\u0631\u0627\u062c\u0639\u064a\u0646 \u0628\u0634\u0631\u064a\u064a\u0646 (\u0628\u0645\u0627 \u0641\u064a \u0630\u0644\u0643 \u0645\u0631\u0627\u062c\u0639\u0648\u0646 \u0645\u062f\u0631\u0651\u0628\u0648\u0646 \u0645\u0646 \u0645\u0632\u0648\u0651\u062f\u064a \u062e\u062f\u0645\u0627\u062a\u0646\u0627) \u0644\u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0639\u0644\u0649 \u062a\u062d\u0633\u064a\u0646 \u0646\u0645\u0627\u0630\u062c\u0646\u0627. \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0636\u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0639\u064a\u0646\u0629\u060c \u0641\u0633\u064a\u062a\u0645 \u0641\u0635\u0644\u0647\u0627 \u0639\u0646 \u062d\u0633\u0627\u0628\u0643 \u0639\u0644\u0649 Google \u0648\u0644\u0646 \u064a\u062a\u0645 \u0631\u0628\u0637\u0647\u0627 \u0628\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649. \u062a\u062d\u062a\u0641\u0638 Google \u0628\u0647\u0630\u0647 \u0627\u0644\u0639\u064a\u0646\u0627\u062a \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0647\u0627 \u0628\u062f\u0648\u0646 \u062a\u062d\u062f\u064a\u062f \u0647\u0648\u064a\u0629 \u0635\u0627\u062d\u0628\u0647\u0627 \u0648\u0644\u0645\u062f\u0629 \u062a\u0635\u0644 \u0625\u0644\u0649 \u062b\u0644\u0627\u062b \u0633\u0646\u0648\u0627\u062a\u060c \u062d\u062a\u0649 \u0644\u0648 \u0642\u0645\u062a \u0628\u062d\u0630\u0641\u0647\u0627 \u0623\u0648 \u0625\u064a\u0642\u0627\u0641 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0644\u0627\u062d\u0642\u064b\u0627. \u064a\u0631\u062c\u0649 \u0639\u062f\u0645 \u0625\u062f\u062e\u0627\u0644 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0633\u0631\u064a\u0629 \u0644\u0627 \u062a\u0631\u063a\u0628 \u0641\u064a \u0623\u0646 \u064a\u0631\u0627\u0647\u0627 \u0645\u0631\u0627\u062c\u0639 \u0623\u0648 \u062a\u0633\u062a\u062e\u062f\u0645\u0647\u0627 Google \u0644\u062a\u062d\u0633\u064a\u0646 \u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0644\u062f\u064a\u0647\u0627.",
"privacy.control":"\u0627\u0644\u0642\u0631\u0627\u0631 \u0628\u064a\u062f\u0643. \u0625\u0630\u0627 \u0643\u0646\u062a \u0644\u0627 \u062a\u0631\u063a\u0628 \u0641\u064a \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u062d\u062a\u0648\u0649 Pomelli \u0627\u0644\u0645\u0633\u062a\u0642\u0628\u0644\u064a \u0627\u0644\u062e\u0627\u0635 \u0628\u0643 (\u0645\u062b\u0644 \u0645\u0644\u0641\u0643 \u0627\u0644\u062a\u062c\u0627\u0631\u064a \u0648\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062d\u0645\u0644\u0627\u062a) \u0628\u0647\u062f\u0641 \u062a\u062f\u0631\u064a\u0628 \u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0627\u0644\u062a\u0648\u0644\u064a\u062f\u064a \u0644\u062f\u064a\u0646\u0627\u060c \u064a\u0645\u0643\u0646\u0643 \u0625\u064a\u0642\u0627\u0641 \u0630\u0644\u0643 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f\u0627\u062a Pomelli \u0641\u064a \u0623\u064a \u0648\u0642\u062a. \u0623\u0645\u0651\u0627 \u0625\u0630\u0627 \u0627\u062e\u062a\u0631\u062a \u062a\u0642\u062f\u064a\u0645 \u0645\u0644\u0627\u062d\u0638\u0627\u062a\u060c \u0641\u064a\u0645\u0643\u0646 \u0644\u0640 Google \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0627 \u0625\u0636\u0627\u0641\u0629\u064b \u0625\u0644\u0649 \u0623\u064a \u0645\u062d\u062a\u0648\u0649 \u0645\u0631\u062a\u0628\u0637 \u0628\u0647\u0627 \u0644\u062a\u062f\u0631\u064a\u0628 \u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0627\u0644\u062a\u0648\u0644\u064a\u062f\u064a \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0646\u0627\u060c \u062d\u062a\u0649 \u0644\u0648 \u0643\u0646\u062a \u0642\u062f \u0623\u0648\u0642\u0641\u062a \u062e\u064a\u0627\u0631 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0644\u0644\u062a\u062f\u0631\u064a\u0628.",
